param(\n    [string]$TargetIp = "192.168.163.252",\n    [int]$Port = 5000,\n    [int]$BitrateMbps = 60,\n    [int]$OutputIndex = 0,\n    [int]$Fps = 60\n)\n\n$ErrorActionPreference = "Stop"\n$ffmpeg = (Get-Command ffmpeg.exe -ErrorAction SilentlyContinue).Source\nif (-not $ffmpeg) {\n    Write-Host "ffmpeg.exe not found in PATH." -ForegroundColor Red\n    Read-Host "Press Enter to exit"\n    exit 1\n}\n$rate = "$($BitrateMbps)M"\n$url = "tcp://$($TargetIp):$($Port)?tcp_nodelay=1"\n$gop = [Math]::Max(15, [Math]::Round($Fps / 4))\nWrite-Host "Veyra TCP sender -> $TargetIp`:$Port"\nWrite-Host "HEVC AMF $BitrateMbps Mbps, $Fps fps, TCP_NODELAY"\nWrite-Host "Press Ctrl+C to stop."\n& $ffmpeg -hide_banner `\n    -filter_complex "ddagrab=output_idx=$($OutputIndex):framerate=$($Fps):draw_mouse=1,setpts=N/($($Fps)*TB)" `\n    -an `\n    -c:v hevc_amf `\n    -usage ultralowlatency `\n    -quality speed `\n    -latency 1 `\n    -preanalysis 0 `\n    -preencode 0 `\n    -vbaq 0 `\n    -rc cbr `\n    -b:v $rate `\n    -maxrate $rate `\n    -bufsize 2M `\n    -g $gop `\n    -gops_per_idr 1 `\n    -bf 0 `\n    -async_depth 1 `\n    -header_insertion_mode gop `\n    -muxdelay 0 `\n    -muxpreload 0 `\n    -flush_packets 1 `\n    -f mpegts `\n    $url\nexit $LASTEXITCODE